for f in fs:
 s=f.read_text(encoding='utf-8'); lines=s.splitlines(); rel=f.as_posix()
 # frontmatter
 if not (lines and lines[0].strip()=='---'): issues['无 YAML frontmatter'].append((rel,1,''))
 else:
  try: end=next(i for i,x in enumerate(lines[1:],1) if x.strip()=='---')
  except StopIteration: issues['frontmatter 未闭合'].append((rel,1,''))
 # headings outside fences
 inf=False; hs=[]
 for i,l in enumerate(lines,1):
  if re.match(r'^\s*```',l): inf=not inf; continue
  if inf: continue
  m=re.match(r'^(#{1,6})\s+(.+)',l)
  if m: hs.append((i,len(m.group(1)),m.group(2)))
 if not any(x[1]==1 for x in hs): issues['缺少 H1'].append((rel,1,''))
 if len([x for x in hs if x[1]==1])>1: issues['多个 H1'].append((rel,[x[0] for x in hs if x[1]==1],''))
 for a,b in zip(hs,hs[1:]):
  if b[1]>a[1]+1: issues['标题跳级'].append((rel,b[0],f'H{a[1]}→H{b[1]}'))
 # style scanning outside fence
 inf=False
 ul=set(); ol=[]
 for i,l in enumerate(lines,1):
  if re.match(r'^\s*```',l): inf=not inf; continue
  if inf: continue
  m=re.match(r'^(\s*)([-+*])\s+',l)
  if m: ul.add(m.group(2))
  m=re.match(r'^\s*(\d+)\.\s+',l)
  if m: ol.append((i,int(m.group(1))))
  if '__' in l: issues['双下划线强调'].append((rel,i,l.strip()[:80]))
  # underscore italic approximate
  if re.search(r'(?<!\w)_[^_\n]+_(?!\w)',l): issues['下划线斜体'].append((rel,i,l.strip()[:80]))
  if re.search(r'<\/?(?:details|summary|br|div|span|table|tr|td|p|center|font|img)\b',l,re.I): issues['HTML 残留'].append((rel,i,l.strip()[:100]))
  if '[TOC]' in l: issues['[TOC] 残留'].append((rel,i,l.strip()))
  if re.search(r'(?<!\!)\[ \]',l): issues['空任务框'].append((rel,i,l.strip()[:100]))
  # markdown image
  if re.search(r'!\[[^]]*\]\([^)]+\)',l): issues['Markdown 图片语法'].append((rel,i,l.strip()[:100]))
  # malformed wiki candidates
  if re.search(r'(?<!!)\[\[[^\]]*$|(?<!\[)\[[^\[]*\]\]',l): pass
 if len(ul)>1: issues['无序列表标记混用'].append((rel,1,''.join(sorted(ul))))
 # ordered list explicit nums >1
 if any(n!=1 for _,n in ol): issues['有序列表显式编号'].append((rel,next(i for i,n in ol if n!=1),''))
 # Tables validate separator existence & pipe columns
 for i,l in enumerate(lines[:-1],1):
  if '|' in l and re.match(r'^\s*\|?.*\|.*\|?\s*$',l) and re.match(r'^\s*\|?\s*:?-{3,}',lines[i]):
   def cols(x): return len([z for z in x.strip().strip('|').split('|')])
   c=cols(l); j=i
   while j<len(lines) and '|' in lines[j] and lines[j].strip():
    if cols(lines[j])!=c: issues['表格列数不一致'].append((rel,j+1,f'{cols(lines[j])}!={c}'))
    j+=1
 # links syntax broad
 for i,l in enumerate(lines,1):
  if re.search(r'\[[^\]]+\]\([^)]*$',l): issues['疑似损坏 Markdown 链接'].append((rel,i,l.strip()[:100]))
print(json.dumps({k:{'files':len(set(x[0] for x in v)),'count':len(v),'examples':v[:12]} for k,v in issues.items()},ensure_ascii=False,indent=2))
